def embed_text(text):
    # a shared embedding space across modalities
    return [ord(c) % 10 for c in text[:8]]

def embed_image_caption(caption):
    # a shared embedding space across modalities
    return embed_text(caption)

items = [
    {"type": "text", "content": "The Falcon plan costs twenty dollars per month.", "embedding": embed_text("Falcon plan pricing")},
    {"type": "image", "content": "pricing_chart.png", "caption": "Falcon plan pricing chart", "embedding": embed_image_caption("Falcon plan pricing chart")},
    {"type": "text", "content": "Refunds are processed within five business days.", "embedding": embed_text("Refund policy")},
]

def cosine_like_score(a, b):
    return sum(1 for x, y in zip(a, b) if x == y)

def multi_modal_retrieve(query, items, top_k=2):
    # retrieving across mixed content types
    query_embedding = embed_text(query)
    scored = sorted(items, key=lambda i: cosine_like_score(i["embedding"], query_embedding), reverse=True)
    return scored[:top_k]

results = multi_modal_retrieve("Falcon plan pricing", items)
print("Multi-modal retrieval result:")
for r in results:
    print(f" [{r['type']}] {r['content']}")
